
values ('school-content-media','school-content-media',false,262144000,array['application/pdf','video/mp4','video/webm','video/quicktime','image/jpeg','image/png','image/webp']::text[])
on conflict (id) do update set
  file_size_limit=excluded.file_size_limit,
  allowed_mime_types=excluded.allowed_mime_types;

alter table public.multaqa_calendar_events
  add column if not exists source_key text,
  add column if not exists source_kind text;

create unique index if not exists uq_multaqa_calendar_events_source_key
  on public.multaqa_calendar_events(source_key)
  where source_key is not null;

on conflict (source_key) where source_key is not null do update set
  title=excluded.title,
  event_date=excluded.event_date,
  event_time=excluded.event_time,
  details=excluded.details,
  reminder_days=excluded.reminder_days,
  audience=excluded.audience,
  published=excluded.published,
  updated_at=now();
